import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    pairs = []
    for _ in range(n):
        a = int(next(iterator))
        b = int(next(iterator))
        pairs.append((a, b))

    # Get all prime factors from all numbers in all pairs
    # We will collect potential candidates (prime factors)
    candidates = set()

    for a, b in pairs:
        x = a
        y = b

        # Factorize x
        d = 2
        temp = x
        while d * d <= temp:
            if temp % d == 0:
                candidates.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            candidates.add(temp)

        # Factorize y
        d = 2
        temp = y
        while d * d <= temp:
            if temp % d == 0:
                candidates.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            candidates.add(temp)

    if not candidates:
        print("-1")
        return

    # Check each candidate
    for cand in candidates:
        valid = True
        for a, b in pairs:
            # Check if cand divides a or b
            if a % cand != 0 and b % cand != 0:
                valid = False
                break
        if valid:
            print(cand)
            return

    print("-1")

if __name__ == "__main__":
    solve()
